WITH long_format AS (SELECT id, supplier_id, kpi, value FROM (SELECT id, supplier_id, price, cost FROM products) src UNPIVOT (value FOR kpi IN (price, cost))) SELECT CASE WHEN value >= 75 THEN 'HIGH' ELSE 'LOW' END AS value_tier, MAX(value) FILTER (WHERE kpi = 'cost') AS cost_max_value, COUNT(*) AS cnt, PERCENTILE_APPROX(value, ARRAY(0.25, 0.5, 0.75)) AS value_quartiles FROM long_format GROUP BY CASE WHEN value >= 75 THEN 'HIGH' ELSE 'LOW' END;
